// --- Store original rule-based values for audit ---
const ruleResults = {
  rule_score: originalInput.score,
  rule_tier: originalInput.tier,
  rule_action: originalInput.action,
  rule_processing_status: originalInput.processing_status,
  rule_needs_review: originalInput.needs_review,
};

// --- Apply overrides with conservative policy ---
let finalScore = originalInput.score;
let finalTier = originalInput.tier;
let finalAction = originalInput.action;
let finalStatus = originalInput.processing_status;
let finalNeedsReview = originalInput.needs_review;
let actionNote = originalInput.action_note || '';
const overrideLog = [];

// 1. Spam override
if (evaluation.spam_assessment.override_status) {
  const ruleStatus = originalInput.processing_status;
  const llmStatus = evaluation.spam_assessment.override_status;

  if (ruleStatus !== llmStatus) {
    if (llmStatus === 'spam' && ruleStatus !== 'spam') {
      // LLM caught spam that rules missed
      finalStatus = 'spam';
      finalScore = 0;
      finalTier = 'spam';
      finalAction = 'archive';
      overrideLog.push('spam_detected: ' + ruleStatus + ' -> spam');
    } else if (llmStatus === 'ok' && (ruleStatus === 'spam' || ruleStatus === 'spam_suspected')) {
      // LLM says legitimate but rules flagged spam — trust LLM but flag review
      finalStatus = 'ok';
      finalNeedsReview = true;
      overrideLog.push('spam_cleared: ' + ruleStatus + ' -> ok (review flagged)');
    } else if (llmStatus === 'spam_suspected' && ruleStatus !== 'spam_suspected') {
      finalStatus = 'spam_suspected';
      finalNeedsReview = true;
      overrideLog.push('spam_suspected: ' + ruleStatus + ' -> spam_suspected');
    }
  }
}

// 2. Score/tier override (only if not spam-overridden to 0)
if (finalTier !== 'spam' && finalStatus !== 'spam') {
  if (!evaluation.score_assessment.rule_score_fair) {
    const oldScore = finalScore;
    const oldTier = finalTier;
    finalScore = Math.max(0, Math.min(100, evaluation.score_assessment.adjusted_score));
    finalTier = evaluation.score_assessment.adjusted_tier;
    overrideLog.push('score: ' + oldScore + ' -> ' + finalScore + ', tier: ' + oldTier + ' -> ' + finalTier);
  }
}

// 3. Action override
if (evaluation.action_assessment.override_action) {
  const oldAction = finalAction;
  finalAction = evaluation.action_assessment.override_action;
  if (oldAction !== finalAction) {
    overrideLog.push('action: ' + oldAction + ' -> ' + finalAction);
  }
}

// 4. Red flags -> always flag for review
if (evaluation.red_flags && evaluation.red_flags.length > 0) {
  finalNeedsReview = true;
}

// 5. Fabricated institution -> downgrade
if (evaluation.institution_assessment.verdict === 'fabricated_likely') {
  finalNeedsReview = true;
  if (finalAction === 'schedule_call') {
    finalAction = 'manual_review';
    overrideLog.push('institution_fabricated: downgraded to manual_review');
  }
}

// 6. Suspicious/unreasonable fee -> downgrade
if (evaluation.fee_assessment.verdict === 'suspicious_fraud' || evaluation.fee_assessment.verdict === 'unreasonable') {
  finalNeedsReview = true;
  if (finalAction === 'schedule_call') {
    finalAction = 'manual_review';
    overrideLog.push('fee_' + evaluation.fee_assessment.verdict + ': downgraded to manual_review');
  }
}

// 7. Audience mismatch -> downgrade
if (evaluation.audience_fit_assessment.verdict === 'no_fit') {
  if (finalTier === 'high' || finalTier === 'medium') {
    const oldTier = finalTier;
    finalTier = 'low';
    overrideLog.push('audience_no_fit: tier ' + oldTier + ' -> low');
  }
  if (finalAction === 'schedule_call' || finalAction === 'share_options') {
    finalAction = 'manual_review';
    overrideLog.push('audience_no_fit: action -> manual_review');
  }
  finalNeedsReview = true;
}

// 8. Multiple programmes detected -> flag for review
if (originalInput.multiple_programmes_detected && originalInput.programme_count > 1) {
  finalNeedsReview = true;
  if (!overrideLog.some(l => l.includes('multi_programme'))) {
    overrideLog.push('multi_programme: ' + originalInput.programme_count + ' programmes detected');
  }
}

// Build action note
if (overrideLog.length > 0) {
  const prefix = actionNote ? actionNote + '. ' : '';
  actionNote = prefix + 'LLM eval: ' + overrideLog.join('; ');
}

return [{
  json: {
    ...originalInput,
    // Overridden fields
    score: finalScore,
    tier: finalTier,
    action: finalAction,
    processing_status: finalStatus,
    needs_review: finalNeedsReview,
    action_note: actionNote,
    // Audit trail
    eval_status: 'completed',
    eval_rule_results: ruleResults,
    eval_spam: evaluation.spam_assessment,
    eval_institution: evaluation.institution_assessment,
    eval_fee: evaluation.fee_assessment,
    eval_audience_fit: evaluation.audience_fit_assessment,
    eval_score: evaluation.score_assessment,
    eval_action: evaluation.action_assessment,
    eval_red_flags: evaluation.red_flags,
    eval_confidence: evaluation.overall_confidence,
    eval_overrides: overrideLog,
  }
}];
